package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.bukkit.configuration.file.YamlConfiguration; import java.io.*;
public class WarpModule extends AbstractModule {private final File f;private final YamlConfiguration c;public WarpModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());f=new File(p.getDataFolder(),"configs/Warps.yml");c=YamlConfiguration.loadConfiguration(f);}public String id(){return "Warp";}public String description(){return "公共传送点管理 /warp";}public boolean handle(CommandSender s,String l,String[] a){if(a.length==0){plugin.msg(s,"&e/warp <名称> | /warp set/delete <名称>");return true;}if(a[0].equalsIgnoreCase("set")||a[0].equalsIgnoreCase("delete")){if(!s.hasPermission("fuzhu.admin")){plugin.msg(s,"&c你没有权限。");return true;}if(a.length<2){plugin.msg(s,"&e缺少名称。");return true;}String k="warps."+a[1];if(a[0].equalsIgnoreCase("set")){Player p=ModuleUtil.player(plugin,s);if(p==null)return true;c.set(k,p.getLocation());plugin.msg(s,"&a传送点已设置。");}else{c.set(k,null);plugin.msg(s,"&a传送点已删除。");}save();return true;}Player p=ModuleUtil.player(plugin,s);if(p!=null&&c.isLocation("warps."+a[0])){p.teleport(c.getLocation("warps."+a[0]));plugin.msg(s,"&a传送成功。");}else plugin.msg(s,"&c传送点不存在。");return true;}private void save(){try{c.save(f);}catch(IOException ignored){}}}
